"use strict";(globalThis.webpackChunksanctuary_amongst_the_starts=globalThis.webpackChunksanctuary_amongst_the_starts||[]).push([[4716],{6864(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>r,metadata:()=>s,toc:()=>h});const s=JSON.parse('{"id":"world-information/locations/outer-system/jupiter","title":"Jupiter","description":"---","source":"@site/docs/world-information/locations/outer-system/jupiter.md","sourceDirName":"world-information/locations/outer-system","slug":"/world-information/locations/outer-system/jupiter","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/jupiter","draft":false,"unlisted":false,"editUrl":"https://github.com/kaelynj/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/jupiter.md","tags":[],"version":"current","frontMatter":{},"sidebar":"loreSidebar","previous":{"title":"Venus","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/inner-system/venus"},"next":{"title":"The Kuiper Belt & Oort Cloud","permalink":"/sanctuary-amongst-the-stars/docs/world-information/locations/outer-system/kuiper-belt-oort-cloud"}}');var i=n(4848),a=n(8453);const r={},o="Jupiter",l={},h=[{value:"The Angry God",id:"the-angry-god",level:2},{value:"Jovian Life",id:"jovian-life",level:2},{value:"Jovian Settlements",id:"jovian-settlements",level:2},{value:"Solano (Amalthea)",id:"solano-amalthea",level:3},{value:"Europa",id:"europa",level:3},{value:"Ganymede",id:"ganymede",level:3},{value:"Liberty",id:"liberty",level:3},{value:"Callisto",id:"callisto",level:3},{value:"Hyoden",id:"hyoden",level:3},{value:"The Jovian Trojans",id:"the-jovian-trojans",level:2},{value:"Pirates",id:"pirates",level:3},{value:"Locus",id:"locus",level:3}];function c(e){const t={em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"jupiter",children:"Jupiter"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Posted By:"})," ",(0,i.jsx)(t.em,{children:"Tio Silencio, Firewall Proxy"})]}),"\n",(0,i.jsx)(t.p,{children:"Understanding the Jovian system means understanding its size, gravity, power, and impact. It is home to the Jovian Republic, with the largest and strongest military presence among transhumanity. Much like Jupiter itself, the Republic's sheer might is both a measuring stick and a force that tugs on every corner of the system."}),"\n",(0,i.jsx)(t.h2,{id:"the-angry-god",children:"The Angry God"}),"\n",(0,i.jsx)(t.p,{children:"Jupiter's size surprises the first-time visitor, especially if you're one of the lucky few who experiences approaching by spacecraft. It's 11 times the diameter of Earth but its day lasts slightly less than ten hours. Its colorful bands, ranging from white to brown to yellow, are beautiful from a distance but hide churning winds and storms unrivaled in the rest of the Solar System. These clouds are mostly hydrogen and helium with a few heavier trace elements; Jupiter lacks the mass to become a star, but not the composition."}),"\n",(0,i.jsx)(t.p,{children:"A faint ring system circles close to the planet, along with over 70 natural satellites, from tiny moonlets to worlds larger than Mercury. Jupiter's immense magnetosphere hangs over our system like a shroud. It washes the Galilean moons, especially Io, with radiation levels so high that unshielded exposure kills within hours if not minutes."}),"\n",(0,i.jsx)(t.h2,{id:"jovian-life",children:"Jovian Life"}),"\n",(0,i.jsx)(t.p,{children:"Life in the Republic is a crucible that forges steel -- or grinds a person to dust. The Fall taught us that transhumanity's follies should not be repeated. The Seventeen-Minute War, the military conflict that left the Jovian system a smoking ruin, taught us that old-Earth power structures would dominate us without concern for our own well-being. And the Consortium takeover of the inner system, along with the autonomist seizure of the rimward system, taught us that we were the last hope for transhumanity's survival."}),"\n",(0,i.jsx)(t.p,{children:"We understand suffering. We know the need for protection, whether from our host planet's radiation belts, the TITANs, or the insipid mistakes of the children around us. Life in the Republic is regimented, authoritarian, and safe if you follow the rules. Nowhere else in the Solar System can make this claim."}),"\n",(0,i.jsx)(t.p,{children:"The Republic does not control every habitat and settlement in the Jovian system. Europa and Callisto remain steadfastly independent, and there are many smaller habs the Republic considers too inconsequential to bother with. Still, access to these areas by physical means is strictly regulated, especially for Republic citizens."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"jovian-settlements",children:"Jovian Settlements"}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Posted By:"})," ",(0,i.jsx)(t.em,{children:"Zoe Elizabeth, Firewall Proxy"})]}),"\n",(0,i.jsx)(t.p,{children:"Seventy million transhumans live within Jupiter's influence. Carving out settlements here is challenging, especially considering the Junta's bioconservative policies restricting radiation-hardened morphs. The closer to the planet one gets, the harder it becomes to shield a hab against radiation. On larger moons, stations are buried far underground. Smaller moonlets are hollowed out into Regan cylinders, spun for gravity, using their natural rock as buffers. It's not without reason that the rest of transhumanity considers them unsafe, unstable, and worthless, unless you're trying to pack a bunch of people into one place and keep them under control. In other words -- perfect for the Junta."}),"\n",(0,i.jsx)(t.h3,{id:"solano-amalthea",children:"Solano (Amalthea)"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Habitat Type:"})," Regan Cylinder"]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Allegiance:"})," Jovian Republic"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"Solano is considered the nicest of the Reagan cylinders. It's a government and hypercorp research lab with a focus on military tech. Access is strictly controlled by patrol ships and killsats. Despite the high level of security, there have been a handful of terrorist attacks on Solano. The Junta places the blame firmly on the Autonomist Alliance and anarchist factions in the Jovian system. Whether this is true, hawks within the Republic consider it a casus belli."}),"\n",(0,i.jsx)(t.h3,{id:"europa",children:"Europa"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Allegiance:"})," Independent (Europan Parliament)"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"No briefing on Europa does it justice; the moon is best experienced firsthand. Yes, there is native life under the ice. It evolved there for billions of years, completely independent of life on Earth. Scientists have been studying this life since before the Fall, and it was from those original science colonies that the Europan Parliament grew, an independent democracy entirely apart from the Junta. Europa is a minor state compared to the Republic or the Consortium. It is perfectly content to exist unmolested, though it maintains a minor protective militia."}),"\n",(0,i.jsx)(t.p,{children:"Europa sits deep within Jupiter's magnetosphere; apart from a few surface structures, everyone lives in massive bubble warrens carved into the ice dozens of kilometers below the surface. Conamara is the only major surface habitat; it acts as the elevator head for goods shipped to and from the oceans below. Tens of thousands of Europans have fully embraced life in the cold, dense, saltwater oceans, sleeved in heavily modified biomorphs and synthmorphs."}),"\n",(0,i.jsx)(t.p,{children:"Europan culture is unique. Education and the sciences are highly valued, and Europa has the highest rate of advanced degrees in the Solar System. Undersea life has given rise to new sports, from races to aquatic orienteering."}),"\n",(0,i.jsx)(t.h3,{id:"ganymede",children:"Ganymede"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Allegiance:"})," Jovian Republic"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"Ganymede is the largest moon in the Solar System -- larger than Mercury -- and the largest population center in the Republic. Everything on or near Ganymede is a member of protectorate of the Republic. The moon is tidally locked, and while it isn't as far inside the magnetosphere as Io or Europa, an unprotected morph on the surface takes lethal doses of radiation in less than an hour. Most of its settlements are deep underground, buried in a honeycomb of caverns and tunnels that cut through the entire moon. A few dot the surface, existing to service those deeper."}),"\n",(0,i.jsx)(t.p,{children:"The Castle is the Junta's information and data repository. It's an open secret that this is where the Junta surveils its citizens. Non-AI data analysts comb through mesh traffic, entertainment feeds, security data, surveillance chatter, the latest XPorn, love letters, and primary school art projects. Everything is tagged, classified, and filed, censored where appropriate, and routed to the correct authorities. Entry is limited ot a single shuttle on a single route: other ships are destroyed by killsat."}),"\n",(0,i.jsx)(t.p,{children:"Several habitats orbit Ganymede; the Holy See (or New Vatican) is the home of the Roman Catholic Church in exile. It's a Regan cylinder upgraded to the point of opulence and houses many of the artifacts the Church has rescued from Earth. It serves as school for biblical scholarship, a museum, and the de facto heart of post-Fall Christianity."}),"\n",(0,i.jsx)(t.h3,{id:"liberty",children:"Liberty"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Habitat Type:"})," Subsurface/Cluster"]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Allegiance:"})," Jovian Republic"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"Liberty is the capital and largest city in the Jovian Republic. It's a mix of deep factories and farms churning out the materials to keep the Republic running, a government town where lobbyists and moralists compete for time with the Senate, and an authoritarian police state. People here wake up, go to work, come home, and keep their heads down."}),"\n",(0,i.jsx)(t.p,{children:"Venture far enough into the outer tunnels and deep chambers of Liberty and the Junta's control recedes. These are, remarkably, some of the poorest and most dangerous slums in the Solar System. Some areas are such a crime-ridden free-for-all that security forces refuse to enter; the Junta simply acts like the people there don't exist."}),"\n",(0,i.jsx)(t.p,{children:"Liberty Station hangs in geosynchronous orbit over the city. A space elevator was planned to connect the two, but the project was abandoned when resources were redirected. The station is the main shipyard for the Junta; the Space Force keeps a quarter of its fleet here at any time, and the spiderweb-like arms and legs jutting out from the original asteroid supply hundreds of ships in various stages of construction or refit."}),"\n",(0,i.jsx)(t.h3,{id:"callisto",children:"Callisto"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Allegiance:"})," Independent/Jovian Republic"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"Callisto is the furthest Galilean moon from Jupiter and the farthest from the Junta's clutches. It's a crater-pocked wasteland with little going for it except its distance from Jupiter's radiation belts. Several city-states dot Callisto. The Republic claims them as protectorates, but the city-states see themselves as independent."}),"\n",(0,i.jsx)(t.h3,{id:"hyoden",children:"Hyoden"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Habitat Type:"})," Subsurface"]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Allegiance:"})," Independent"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"Prior to the Fall, Hyoden was a backwater with poor supplies and a massive labor shortage. The settlement accepted more than a million refugees who found the Jovian Republic's policies distasteful or restrictive. In exchange for a synthetic morph, these transhumans were expected to perform three years of military service and help build the settlement. The powerful military city-state that grew from this is independent, cosmopolitan, and proud. AGIs, uplifts, and autonomists are welcomed here; citizenship is open to anyone who serves in the military."}),"\n",(0,i.jsx)(t.p,{children:"Hyoden's embrace of technological advancements give it a distinct advantage over the Republic. This makes Hyoden an increasing threat in the Junta's eyes, but so far the city's layers of missiles, killsats, and turrets have kept the Republic at bay."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"the-jovian-trojans",children:"The Jovian Trojans"}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.strong,{children:"Posted By:"})," ",(0,i.jsx)(t.em,{children:"Homann Kontakt, Sentinel"})]}),"\n",(0,i.jsx)(t.p,{children:"The Trojan (and Greek) asteroids chug happily along at the Sol-Jupiter L4 and L5 points. Most of the residents here are autonomists who want to be away from the Republic but also want a little sunlight. Sprinkle in a few brinkers doing their own thing. Most of 'em are perfectly fine and safe. Most. The sparseness and proximity to the inner system makes this region an ideal hiding spot for pirates and worse kinds of criminals too. Wander too far out of your element and your skull is going to be decorating someone's control console. That's why you need to be prepared."}),"\n",(0,i.jsx)(t.h3,{id:"pirates",children:"Pirates"}),"\n",(0,i.jsxs)(t.p,{children:["The Trojans are an excellent base from which to launch pirate raids. Several of the most notorious pirates to plague the system, like ",(0,i.jsx)(t.em,{children:"Margarita Shun"})," and ",(0,i.jsx)(t.em,{children:"Reboot_Ex"}),", keep hideouts here. They prey on loosely-guarded Republic shipping or automated hypercorp freighters returning sunward. Carbon reaver gangs prefer to hit isolated mining outposts, grabbing the goods before they're shipped out. Pirates use sophisticated hit-and-fade tactics to cover their tracks. Some deploy to-of-the-line synthmorphs and ship weaponry, but most are more devious than well armed."]}),"\n",(0,i.jsx)(t.h3,{id:"locus",children:"Locus"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Habitat Type:"})," Nuestro Shell"]}),"\n",(0,i.jsxs)(t.li,{children:[(0,i.jsx)(t.strong,{children:"Allegiance:"})," Anarchist"]}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"Locus is the largest cluster habitat ever created, spanning a jaw-dropping eleven-kilometer sphere with thousands of modules docked to its wings and spurs. At the center of the cluster floats the Amoeba, a giant sculpture that reshapes itself and changes colors."}),"\n",(0,i.jsx)(t.p,{children:'There is no government or police; tasks are performed by various collectives and a volunteer militia responds to threats and anti-social behavior. The "economy" is based on open nanofab access, gifting, and rep favors, along with the occasional barter.'}),"\n",(0,i.jsx)(t.p,{children:"Locus features everything from artist collectives to arms dealers and mining cooperatives. The Kanigawa Farms feeds the station's inhabitants. The Pill Box is a massive drug lab and party module, where you can experience the latest petals and substances that didn't exist yesterday. Rooktown is a cultural focal point for neo-corvids and mercurial activism. Various maker spaces and hack labs work closely with Exarchia, another Trojan hab that is a nexus for autonomist hacktivism."}),"\n",(0,i.jsx)(t.p,{children:"Boister's Armory, an anti-TITAN research facility, doubles as station security, firing upon any would-be attacker. The work with other collectives for mutual defense of the cluster. Twice the Consortium has attacked Locus, and twice Locus has repelled its would-be oppressors."})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var s=n(6540);const i={},a=s.createContext(i);function r(e){const t=s.useContext(a);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),s.createElement(a.Provider,{value:t},e.children)}}}]);